// Extract error details from the failed execution
const errorData = $input.first().json;

const workflowId = errorData.workflow?.id || 'unknown';
const workflowName = errorData.workflow?.name || 'Unknown Workflow';
const executionId = errorData.execution?.id || 'unknown';
const errorMessage = errorData.execution?.error?.message || 'Unknown error';
const nodeExecutionData = errorData.execution?.data?.resultData?.runData;

// Find which node failed
let failedNode = 'unknown';
if (nodeExecutionData) {
  for (const nodeName of Object.keys(nodeExecutionData)) {
    const runs = nodeExecutionData[nodeName];
    const lastRun = runs && runs.length > 0 ? runs[runs.length - 1] : null;
    if (lastRun?.error || lastRun?.data?.error) {
      failedNode = nodeName;
      break;
    }
  }
}

// Best-effort: recover an invoice id if the failing run carried one
// (webhook body, or the Insert Invoice response before a later node failed)
let invoiceId = null;
if (nodeExecutionData) {
  const webhookRun = nodeExecutionData['Webhook']?.[0];
  const webhookJson = webhookRun?.data?.main?.[0]?.[0]?.json;
  if (webhookJson?.body?.invoiceId) invoiceId = webhookJson.body.invoiceId;
  else if (webhookJson?.invoiceId) invoiceId = webhookJson.invoiceId;

  const insertRun = nodeExecutionData['Insert Invoice']?.[0];
  const insertJson = insertRun?.data?.main?.[0]?.[0]?.json;
  const insertRow = Array.isArray(insertJson) ? insertJson[0] : insertJson;
  if (!invoiceId && insertRow?.id) invoiceId = insertRow.id;
}

return [{
  json: {
    workflowId,
    workflowName,
    executionId,
    failedNode,
    errorMessage,
    invoiceId,
    hasInvoiceId: Boolean(invoiceId),
    timestamp: new Date().toISOString()
  }
}];

// Format error notification message
const e = $input.first().json;

const message = [
  '🚨 *Invoice Ingestion Error*',
  '',
  `*Workflow:* ${e.workflowName}`,
  `*Failed Node:* ${e.failedNode}`,
  `*Error:* ${e.errorMessage}`,
  `*Invoice:* ${e.invoiceId || '(no invoice row — failed before insert)'}`,
  `*Time:* ${e.timestamp}`,
  `*Execution ID:* ${e.executionId}`,
  '',
  'Check n8n execution logs for details.'
].join('\n');

return [{
  json: {
    message,
    subject: `Invoice Ingestion Failed: ${e.failedNode}`
  }
}];
